#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long y1;
    long long y2;
} LinePoint;

typedef struct {
    long long *tree;
    int size;
} Fenwick;

static void fenwick_init(Fenwick *f, int n) {
    f->size = n;
    f->tree = (long long *)calloc(n + 1, sizeof(long long));
}

static void fenwick_add(Fenwick *f, int idx, long long val) {
    for (; idx <= f->size; idx += idx & -idx) {
        f->tree[idx] += val;
    }
}

static long long fenwick_query(Fenwick *f, int idx) {
    long long sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += f->tree[idx];
    }
    return sum;
}

static int cmp_line(const void *a, const void *b) {
    const LinePoint *la = (const LinePoint *)a;
    const LinePoint *lb = (const LinePoint *)b;
    if (la->y1 < lb->y1) return -1;
    if (la->y1 > lb->y1) return 1;
    if (la->y2 < lb->y2) return -1;
    if (la->y2 > lb->y2) return 1;
    return 0;
}

static int cmp_ll(const void *a, const void *b) {
    long long va = *(const long long *)a;
    long long vb = *(const long long *)b;
    if (va < vb) return -1;
    if (va > vb) return 1;
    return 0;
}

static int lower_bound(const long long *arr, int n, long long val) {
    int l = 0, r = n - 1;
    int ans = n;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (arr[mid] >= val) {
            ans = mid;
            r = mid - 1;
        } else {
            l = mid + 1;
        }
    }
    return ans;
}

int main(void) {
    int n;
    long long x1, x2;
    if (scanf("%d %lld %lld", &n, &x1, &x2) != 3) {
        return 0;
    }

    LinePoint *lines = (LinePoint *)malloc(n * sizeof(LinePoint));
    long long *y2_vals = (long long *)malloc(n * sizeof(long long));

    for (int i = 0; i < n; i++) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        lines[i].y1 = a * x1 + b;
        lines[i].y2 = a * x2 + b;
        y2_vals[i] = lines[i].y2;
    }

    qsort(y2_vals, n, sizeof(long long), cmp_ll);

    int unique_y2 = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || y2_vals[i] != y2_vals[i - 1]) {
            y2_vals[unique_y2++] = y2_vals[i];
        }
    }

    qsort(lines, n, sizeof(LinePoint), cmp_line);

    Fenwick bit;
    fenwick_init(&bit, unique_y2);

    long long strictly_separated_pairs = 0;

    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && lines[j].y1 == lines[i].y1) {
            j++;
        }

        for (int k = i; k < j; k++) {
            int rank = lower_bound(y2_vals, unique_y2, lines[k].y2);
            strictly_separated_pairs += fenwick_query(&bit, rank);
        }

        for (int k = i; k < j; k++) {
            int rank = lower_bound(y2_vals, unique_y2, lines[k].y2) + 1;
            fenwick_add(&bit, rank, 1);
        }

        i = j;
    }

    long long total_pairs = (long long)n * (n - 1) / 2;
    long long ans = total_pairs - strictly_separated_pairs;

    printf("%lld\n", ans);

    free(bit.tree);
    free(lines);
    free(y2_vals);

    return 0;
}
